      'ವಾಹನ್ ಬಜಾರ್ ವಾಣಿಜ್ಯ ವಾಹನಗಳು, ನಿರ್ಮಾಣ ಉಪಕರಣಗಳು ಮತ್ತು ವಾಹನ ಸಂಬಂಧಿತ ಸಮಗ್ರ ಸೇವೆಗಳಿಗಾಗಿ ಭಾರತದ ಮೊದಲ ರೀತಿಯ, ಮುಂದಿನ ಪೀಳಿಗೆಯ ಡಿಜಿಟಲ್ ಮಾರುಕಟ್ಟೆಯಾಗಿದೆ.';

