  @override
  String get who_we_are_heading => 'ನಾವು ಯಾರು';

  @override
  String get who_we_are_text_1 =>
      'ನಾವು ಹೈದರಾಬಾದ್ ಮೂಲದ ಆಟೋಮೋಟಿವ್ ಸ್ಟಾರ್ಟಪ್ ಆಗಿದ್ದು, OEM ಗಳು, ಆಫ್ಟರ್‌ಮಾರ್ಕೆಟ್ ಸೇವೆಗಳು, ಮಾರಾಟ ಮತ್ತು ಸ್ಟಾರ್ಟಪ್ ಆವಿಷ್ಕಾರದಲ್ಲಿ ಆಳವಾದ ಅನುಭವ ಹೊಂದಿರುವ ಹಿರಿಯ ವೃತ್ತಿಪರರು ನಮ್ಮನ್ನು ಮುನ್ನಡೆಸುತ್ತಿದ್ದಾರೆ.';

  @override
  String get who_we_are_text_2 =>
      'ಬಲವಾದ ಐಟಿ ಮತ್ತು ಕಾರ್ಯಾಚರಣೆ ಸಾಮರ್ಥ್ಯಗಳೊಂದಿಗೆ, ಭಾರತದಲ್ಲಿ ವಾಹನಗಳನ್ನು ಖರೀದಿಸುವ, ಮಾರಾಟ ಮಾಡುವ ಮತ್ತು ನಿರ್ವಹಿಸುವ ವಿಧಾನವನ್ನು ಮರುವ್ಯಾಖ್ಯಾನಿಸುವುದರ ಮೇಲೆ ನಮ್ಮ ತಂಡ ಗಮನ ಹರಿಸಿದೆ.';

